-- Migrazione per la Fase 2: Social Connections & Feedback -- Creazione delle tabelle 'followers' e 'curator_feedback' con RLS  CREATE EXTENSION IF NOT EXISTS "uuid-ossp";  -- 1. Tabella Followers CREATE TABLE IF NOT EXISTS public.followers (     follower_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,     following_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,     created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,     PRIMARY KEY (follower_id, following_id) );  CREATE INDEX IF NOT EXISTS idx_followers_following_id ON public.followers(following_id);  DO $$ BEGIN     CREATE TYPE feedback_type AS ENUM ('EXCEPTIONAL', 'GOOD', 'AVERAGE', 'POOR'); EXCEPTION     WHEN duplicate_object THEN null; END $$;  CREATE TABLE IF NOT EXISTS public.curator_feedback (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     curator_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,     track_id UUID NOT NULL,     feedback_type feedback_type NOT NULL,     score_modifier DECIMAL(5,2) NOT NULL,     curator_notes TEXT,     evaluated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,     UNIQUE(curator_id, track_id) );  ALTER TABLE public.followers ENABLE ROW LEVEL SECURITY; ALTER TABLE public.curator_feedback ENABLE ROW LEVEL SECURITY;  CREATE POLICY "Chiunque puÃ² vedere i followers" ON public.followers FOR SELECT USING (true); CREATE POLICY "Utenti possono seguire altri" ON public.followers FOR INSERT WITH CHECK (auth.uid() = follower_id); CREATE POLICY "Utenti possono smettere di seguire" ON public.followers FOR DELETE USING (auth.uid() = follower_id);  CREATE POLICY "Chiunque puÃ² leggere il feedback dei curatori" ON public.curator_feedback FOR SELECT USING (true); CREATE POLICY "Solo i curatori possono inserire/aggiornare feedback" ON public.curator_feedback FOR ALL USING (auth.uid() = curator_id);